#!/bin/bash
# Fourth round of faction concept sheets. Direction: each faction is a mixed roster of very different body plans
# (infantry of different builds, a beast, a flyer or floating machine, a huge heavy) tied together only by a shared
# material, colour and ornament language. Same grounded, serious look as round three.
CX="/c/Program Files/WindowsApps/OpenAI.Codex_26.1106.6628.0_x64__2p2nqsd0c76g0/app/resources/codex.exe"
cd "$(dirname "$0")"
mkdir -p concepts
cd concepts
COMMON="Art direction: grounded, serious science-fantasy enemy design for a premium first-person shooter. Believable anatomy, menacing and dignified, weathered functional materials, a restrained palette of two main colours plus ONE glowing accent colour. Not cartoony, not cute, not toy-like, not steampunk. Rendered as high-quality in-game 3D character models. Layout: an enemy faction roster sheet on a plain dark navy background, landscape 16:9, exactly six units in one row, drawn to a consistent scale relative to each other so the size differences are real, clearly separated, neutral poses. THE MOST IMPORTANT RULE: the six units must have six completely different silhouettes and body plans, instantly distinguishable as black shapes: different heights, widths, limb counts, postures and ways of moving. They are NOT the same character in different outfits. They belong together only through shared materials, colours, ornament and the same glowing accent. Original designs only: do not resemble any existing video game's characters. No text, no labels, no logos, no borders, no environment."
gen () { # name prompt
  [ -f "$1.png" ] && { echo "skip $1"; return; }
  "$CX" exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to generate one image: $2 $COMMON Save the resulting PNG into the current directory as $1.png. Reply with only the saved file path." -i ../refs/style_sheet.webp < /dev/null > "$1.log" 2>&1
  [ -f "$1.png" ] && echo "ok $1" || echo "FAIL $1"
}
gen varrik4 "The Varrik: a once-noble spacefaring people fallen into piracy, raiders and scavengers. Shared look: bone-white masks and plates, charcoal leather, deep teal cloth, electric-blue energy accent. The six units, left to right: (1) a RUNT: a small, hunched, scrawny scavenger half the height of the others, bare-limbed, with a knife, scurrying posture. (2) a RAIDER: a tall gaunt long-necked rifleman with digitigrade legs, horned bone mask and a short mantle, holding a long rifle. (3) a HOUND: a lean four-legged hunting beast, hairless and sinewy, wearing a bone mask and a teal harness, low to the ground. (4) a KITE: a flying scout machine, a wide thin wing of stretched teal sailcloth on a bone-white frame with a single blue lamp eye and a small gun slung beneath, clearly airborne. (5) a CAPTAIN: a much taller, broad-shouldered noble with a full teal cape, heavy ornate pauldrons, a tall horned helm, an energy sabre and a glowing blue energy buckler on its forearm. (6) a STRIDER: a huge three-legged walking war machine, a tripod of long jointed legs carrying an armoured pod hung with trophies and cloth banners, with a large cannon and a visible Varrik pilot, towering over everything else." &
gen ordon4 "The Ordon Legion: the disciplined army of an expansionist interstellar empire. Shared look: deep bronze and dark green armour plate over black, clean military forms, glowing amber visors and vents. The six units, left to right: (1) an AUXILIARY: a small, thin, wiry conscript of a different, slighter species, lightly armoured, with a long-barrelled marksman rifle and a single amber eye-lens. (2) a LEGIONARY: a massive broad heavy infantryman sealed in full pressure armour with a domed helmet, carrying a heavy rifle. (3) a BULWARK: an even wider trooper almost hidden behind an enormous rectangular tower shield with an amber energy edge, a short gun poking around it. (4) a WAR BEAST: a thick-necked armoured four-legged beast the size of a bull, with bronze barding plates, a tusked armoured head and an amber-lit collar. (5) a GUNSHIP DRONE: a hovering wedge-shaped armoured flying machine with two underslung guns and amber thrusters, no pilot, clearly airborne. (6) a COLOSSUS: a towering siege trooper twice the height of the legionary, hugely armoured, with a back-mounted rocket pod and a massive two-handed cannon." &
gen hollowed4 "The Hollowed: an ancient death-cult from the deep, spreading a parasitic crystal growth. Shared look: aged bone-coloured chitin like carved armour, near-black flesh, dark wine-red ritual cloth, glowing violet crystal accent. The six units, left to right: (1) a CRAWLER: a small eyeless feral creature scuttling on all fours with long claws, no clothing. (2) a HUSK: a bloated, swollen, staggering carrier with a huge glowing violet crystal sac for a torso and tiny limbs, clearly about to burst. (3) an ACOLYTE: a thin robed upright figure with a smooth eyeless skull-plate and a hooked ritual staff. (4) a KNIGHT: a tall, heavily armoured warrior in fused bone plate with a great cleaver and a jagged bone shield. (5) a SEER: a floating, legless caster in long trailing robes, hovering well above the ground with outstretched clawed hands and a halo of orbiting violet crystal shards. (6) a BEHEMOTH: an enormous hunched four-limbed brute walking on its knuckles, no neck, its back erupting with a ridge of large violet crystals, three times the bulk of the knight." &
gen warden4 "The Wardens: ancient guardian war-machines built by a vanished civilisation, still following their last order. Shared look: carved black stone plates and dark burnished metal, thin pale-gold engraved lines, glowing jade-green light. The six units, left to right: (1) a MITE: a tiny low crawling machine like a stone beetle with six thin legs and one jade light. (2) a SENTRY: a slim upright humanoid frame with a faceless head-plate bearing a vertical band of light and a forearm beam emitter. (3) a LANCER: a tall four-legged machine like a stone stag without a head, long thin legs carrying a body with a single long beam cannon on top. (4) a WATCHER: a hovering machine, a vertical stone spindle surrounded by three slowly orbiting curved plates, with a bright jade eye, clearly floating. (5) a PRAETORIAN: a very large, wide humanoid frame with a fan of stone plates behind its shoulders, a tall hard-light shield and a beam glaive. (6) an OBELISK: a colossal floating war-machine made of separate massive stone slabs arranged around a blazing jade core, with no limbs at all, dwarfing the others." &
wait
echo ALLDONE
